code='''def transform(grid):
    tiles=[]
    for r in range(0,len(grid),6):
        for c in range(0,len(grid[0]),6):
            tiles.append([row[c:c+5] for row in grid[r:r+5]])
    common=max(tiles,key=lambda t:sum(u==t for u in tiles))
    odd=next(t for t in tiles if t!=common)
    result=[row[:] for row in common]
    for r in range(5):
        for c in range(5):
            if odd[r][c]!=common[r][c]:
                result[r][c]=1
    return result
'''
